<?php if(!$posts):?><div class="empty"><h2>Belum ada artikel</h2><p>Konten terbit akan tampil di sini setelah tersedia.</p></div><?php else:?><div class="grid"><?php foreach($posts as $item):?><article class="card"><?php if($item['image']??null):?><img src="/uploads/<?=e($item['image'])?>" alt="<?=e($item['image_alt']??'')?>" width="<?=e((string)$item['image_width'])?>" height="<?=e((string)$item['image_height'])?>" loading="lazy"><?php else:?><div class="placeholder" role="img" aria-label="Gambar belum tersedia">Brainy Journal</div><?php endif?><div class="card-body"><a class="eyebrow" href="/kategori/<?=e($item['category_slug'])?>"><?=e($item['category'])?></a><h3><a href="/berita/<?=e($item['slug'])?>"><?=e($item['title'])?></a></h3><p><?=e(mb_strimwidth(strip_tags($item['excerpt']),0,145,'…'))?></p><time><?=e(fmt_date($item['published_at']))?></time></div></article><?php endforeach?></div><?php endif?>
